// Page blueprints: each has its own hero and its own lineup of sections (in this order, after the hero)
const BLUEPRINTS = {
  A: { name: 'Classic', hero: 'classic', secs: ['features', 'quote', 'cta'], note: 'The style\'s own hero, services, one review and a call to action.' },
  B: { name: 'Cover', hero: 'cover', secs: ['stats', 'features', 'gallery', 'cta'], note: 'A full-bleed photo hero, numbers, services, photos.' },
  C: { name: 'Lead-gen', hero: 'form', secs: ['stats', 'features', 'quote', 'faq', 'cta'], note: 'A request form right in the hero, then proof and answers.' },
  D: { name: 'Editorial', hero: 'strip', secs: ['quote', 'features', 'stats', 'cta'], note: 'A big headline over a strip of three photos, then a featured review.' },
  E: { name: 'Showcase', hero: 'mosaic', secs: ['features', 'quote', 'area', 'cta'], note: 'A photo mosaic beside the headline, services and the towns you serve.' },
  F: { name: 'Split screen', hero: 'half', secs: ['features', 'story', 'faq', 'cta'], note: 'Half text, half photo, then services told as photo stories.' },
  G: { name: 'Product', hero: 'classic', secs: ['features', 'pricing', 'quote', 'faq', 'cta'], note: 'The style\'s own hero, services, prices side by side, a review and answers.' },
  H: { name: 'Magazine', hero: 'magazine', secs: ['gallery', 'features', 'quote', 'cta'], note: 'The business name as a masthead, photos first.' }
};
const BLUEPRINT_IDS = Object.keys(BLUEPRINTS);

const byId = Object.fromEntries(STYLES.map(s => [s.id, s]));
// accepts 'meridian' or 'sl-meridian'
const get = (id) => byId[String(id || '').startsWith(PREFIX) ? String(id).slice(PREFIX.length) : String(id || '')] || null;
const isLib = (styleId) => String(styleId || '').startsWith(PREFIX) && !!get(styleId);

const HEX = /^#[0-9a-f]{6}$/i;
const mix = (a, b, t) => { const x = contrast.parseHex(a), y = contrast.parseHex(b); return contrast.toHex(x.map((v, i) => v + (y[i] - v) * t)); };

// The style's own brand and accent colors, offered in the editor like the approved styles' palettes.
// The accent is a darker companion of the brand color (SiteGen uses it for dark bands and gradients).
function palette(st) {
  const a2 = st.c.accent2;
  const base = contrast.luminance(a2) < 0.2 ? a2 : mix(st.c.accent, st.c.text, 0.55);
  // white text sits on it (closing band, dark sections), so it is kept dark enough for that
  return { primary: st.c.accent, accent: contrast.ensureContrast(base, '#ffffff', contrast.AA_TEXT) };
}

// Which page blueprint the home page uses: the owner's pick, or the style's own
const blueprintOf = (st, theme) => (BLUEPRINT_IDS.includes((theme || {}).slBlueprint) ? theme.slBlueprint : st.bp);

// The --t-* tokens the Style Library page reads. The client's brand color (theme.primaryColor) replaces the
// style's accent; colors used as small text get their own readable version.
function tokens(st, theme) {
  theme = theme || {};
  const c = { ...st.c };
  const dark = st.mode === 'Dark';
  if (dark && HEX.test(theme.bgColor || '')) c.bg = theme.bgColor;
  if (HEX.test(theme.primaryColor || '') && theme.primaryColor.toLowerCase() !== c.accent.toLowerCase()) {
    c.accent = theme.primaryColor; c.on = contrast.textOn(c.accent);
  }
  // a button label below 4.5:1 switches to whichever of light or dark reads better
  if (contrast.ratio(c.on, c.accent) < contrast.AA_TEXT && contrast.ratio(contrast.textOn(c.accent), c.accent) > contrast.ratio(c.on, c.accent)) c.on = contrast.textOn(c.accent);
  const ink = contrast.ensureContrast(c.accent, c.bg, contrast.AA_TEXT);
  const ink2 = contrast.ensureContrast(c.accent2, c.bg, contrast.AA_LARGE);
  const hi = contrast.ensureContrast(st.hi || c.accent, '#262626', contrast.AA_TEXT);   // emphasis on a darkened photo
  const f = st.fonts;
  const shadow = st.shadow || (dark ? '0 30px 80px -24px rgba(0,0,0,.65)' : '0 26px 60px -28px color-mix(in srgb, ' + c.text + ' 35%, transparent)');
  return [
    '--t-script:' + (f.script || 'var(--t-display)'), '--t-stk:' + (c.stk || c.accent2), '--t-stk-ink:' + (c.stkInk || c.text), '--t-stamp:' + (c.stamp || ink),
    '--t-hi:' + hi, '--t-accent3:' + (c.accent3 || c.accent2), '--t-bw:' + (st.bw || '1px'), '--t-cshadow:' + (st.cshadow || 'none'), '--t-bshadow:' + (st.bshadow || 'none'),
    '--t-bborder:' + (st.bborder || 'transparent'), '--t-ghost:' + (st.ghost || 'color-mix(in srgb, ' + c.text + ' 24%, transparent)'),
    '--t-bg:' + c.bg, '--t-surface:' + c.surface, '--t-text:' + c.text, '--t-muted:' + c.muted, '--t-accent:' + c.accent, '--t-accent2:' + c.accent2,
    '--t-accent-ink:' + ink, '--t-accent2-ink:' + ink2, '--t-line:' + c.line, '--t-on:' + c.on, '--t-mark:' + (c.mark || c.accent2),
    // the site's heading and body fonts: the style's own unless the owner picked others
    '--t-display:var(--heading-font)', '--t-body:var(--body-font)', '--t-mono:' + f.mono, '--t-dw:' + f.dw, '--t-dls:' + f.dls, '--t-dtt:' + (f.dtt || 'none'),
    '--t-h1s:' + f.h1 + 'px', '--t-h2s:' + f.h2 + 'px', '--t-r:' + st.r + 'px', '--t-br:' + st.br, '--t-shadow:' + shadow,
    'color-scheme:' + (dark ? 'dark' : 'light')
  ].join(';');
}

// The attributes on the page wrapper: headline emphasis, glass cards, float shape, pill nav
const wrapAttrs = (st) => `data-emph="${st.emph}"${st.glass ? ' data-glass' : ''}${st.floatStyle ? ` data-float="${st.floatStyle}"` : ''}`;

// Google Fonts: the first family is the display font, the rest (body, mono, script) ride along with the body font
function fontParams(st) {
  const parts = st.gf.split('&family=');
  return { heading: parts[0], body: parts.slice(1).join('&family=') };
}

// A few words for the style picker: the part before the colon, or the first phrase
function shortDesc(st) {
  let t = st.desc.split(/[,.:]|\s(?:with|over)\s/)[0];
  if (t.length > 44) t = t.slice(0, 44).replace(/\s+\S*$/, '');
  return t.charAt(0).toLowerCase() + t.slice(1);
}

// Each style as a SiteGen theme, so every page of the site (not only the home page) takes its look
function themeEntry(st) {
  const c = st.c, f = st.fonts, dark = st.mode === 'Dark';
  const fp = fontParams(st);
  const r = st.r;
  const brutal = !!st.bborder;
  const lines = [
    `h1, h2, h3 { font-weight: ${f.dw}; letter-spacing: ${f.dls};${f.dtt ? ` text-transform: ${f.dtt};` : ''} }`,
    `.btn, nav.site-nav .links a.nav-cta, nav.site-nav .nav-cta { border-radius: ${st.br === '0' ? '0' : st.br};${brutal ? ` border: ${st.bw || '2px'} solid ${st.bborder}; box-shadow: ${st.bshadow};` : ''} }`,
    '.section-head .rule { background: var(--primary); }',
    // the closing band keeps white text readable even when the brand color is light
    '.cta-band { background: linear-gradient(135deg, var(--accent), color-mix(in srgb, var(--accent) 72%, var(--primary))); }'
  ];
  if (brutal) lines.push(`.card, .contact-card, .testimonial-card, .feat-card, .price-card { border: ${st.bw || '2px'} solid ${st.bborder}; box-shadow: ${st.cshadow}; }`);
  if (dark) lines.push(
    'nav.site-nav { background: color-mix(in srgb, var(--page-bg) 92%, transparent); border-bottom: 1px solid var(--border); }',
    'nav.site-nav .links a:not(.nav-cta) { color: var(--ink); }',
    '.card, details.faq-item, .contact-card, .service-links a, .testimonial-card, .review-card, .feat-card, .step-card, .hero-card, .price-card { background: var(--surface); border: 1px solid var(--border); color: var(--ink); }',
    '.contact-form input, .contact-form textarea, .contact-form select, .quote-form input, .quote-form textarea, .quote-form select { background: var(--page-bg); color: var(--ink); border-color: var(--border); }',
    '.cookie-bar, .mobile-bar, .skip-link { background: var(--surface); color: var(--ink); }',
    '.top-bar { background: color-mix(in srgb, var(--page-bg) 70%, black); }',
    'footer.site-footer { background: color-mix(in srgb, var(--page-bg) 78%, black); border-top: 1px solid var(--border); }'
  );
  return {
    id: PREFIX + st.id, lib: true, dark, label: `${st.name} (${shortDesc(st)})`, home: 'stylelib', hero: st.hero === 'center' ? 'center' : 'left',
    heading: { name: f.dName, param: fp.heading, css: f.display },
    body: { name: f.bName, param: fp.body, css: f.body },
    palette: palette(st),
    vars: {
      '--ink': c.text, '--muted': c.muted, '--page-bg': c.bg, '--surface': c.surface, '--border': c.line,
      '--radius': r + 'px', '--radius-sm': Math.round(r * 0.6) + 'px',
      '--shadow-sm': st.cshadow || (dark ? '0 1px 2px rgba(0,0,0,0.5)' : '0 1px 3px color-mix(in srgb, ' + c.text + ' 10%, transparent)'),
      '--shadow-md': st.shadow || (dark ? '0 14px 40px rgba(0,0,0,0.55)' : '0 14px 34px color-mix(in srgb, ' + c.text + ' 14%, transparent)')
    },
    css: lines.join('\n')
  };
}
const THEME_ENTRIES = STYLES.map(themeEntry);

// The editor's description of each look. A few of the original descriptions name sample content from the library
// file (a live chart, carrier logos, a wait-time card); here they describe only what a client's site will show.
const LOOK = {
  meridian: 'Quiet authority: deep navy, a refined serif with italics and hairline rules.',
  slate: 'Crisp product marketing: monochrome slate, one electric blue and a fine grid.',
  polar: 'Calm clinical clarity: ice white, teal, a friendly geometric sans and an info card up front.',
  'harbor-blue': 'Confident and trustworthy: royal blue with warm amber and a rounded modern sans.',
  onyx: 'Premium dark product site: soft blue glow and a clean modern grotesk.',
  sandstone: 'Refined and warm: stone neutrals, walnut brown, an elegant Garamond with italics and a dotted-leader price menu.',
  fieldstone: 'Grounded and steady: deep evergreen, soft cream type and a clean grotesk.',
  atrium: 'Warm and reassuring: soft daylight, slate blue with honey and a gentle serif with italics.',
  'picnic-table': 'Red gingham, wild-west wood type, a receipt-style info card and a tilted ticker.',
  'topo-trail': 'Topographic contour lines, sage and rust, a tear-off ticket card and a passport-stamp headline.',
  'cover-story': 'A glossy magazine cover: giant masthead, issue line, a taped-on card and handwritten script.',
  'arcade-after-dark': 'Synthwave: a striped sunset, a neon grid floor, an app-window card and a giant closer.',
  'barber-pole': 'Old-school shop: a striped pole, slab-serif signage, a printed ticket card and a dotted-leader price menu.',
  starfield: 'Deep space: scattered stars, a rising golden planet, wide spacey type and a phone-shaped info card.',
  'comic-book': 'Sunday funnies: halftone dots, ink outlines, sticker headlines and a giant closer.'
};
STYLES.forEach(st => { st.look = LOOK[st.id] || st.desc; });

// One line per style for the editor: what it looks like and the kind of business it was designed for
const HINTS = Object.fromEntries(STYLES.map(st => [PREFIX + st.id, `Style Library, ${BLUEPRINTS[st.bp].name} blueprint. ${st.look} Designed for ${st.industry.toLowerCase()}.`]));

// Styles whose industry fits a business type, in library order
const INDUSTRY_WORDS = {
  'Wealth & finance': /financ|wealth|invest|advis|planner|bank|credit union/i, 'Software & SaaS': /software|saas|\bapps?\b|startup|payroll/i,
  'Consulting & advisory': /consult|advisory|strategy|coach/i, Healthcare: /health|urgent care|medical|doctor|physician|chiro|therap|pediatric/i,
  'Architecture & design': /architect|design studio/i, Insurance: /insur/i, 'SaaS & analytics': /software|saas|analytics|\bdata\b/i,
  'Interior design': /interior|decorat/i, 'Staffing & HR': /staffing|recruit|\bhr\b|hiring|employment/i, 'Property management': /property|landlord|\bhoa\b/i,
  'Senior living & care': /senior|assisted living|elder|memory care|nursing/i, 'Corporate law & finance': /law|attorney|lawyer|legal|\bcpa\b/i,
  'Phone & tech repair': /phone|computer repair|tech repair|it repair|electronics/i, 'BBQ & catering': /bbq|barbecue|smokehouse|cater/i,
  'Tours & outdoors': /\btours?\b|kayak|outdoor|adventure|eco.?tour/i, 'Real estate': /real estate|realtor|realty|broker/i,
  'HVAC & trades': /hvac|air condition|\bac\b|heating|plumb|electric/i, 'Party rentals': /party|bounce|inflatable|event rental/i,
  'Entertainment & bars': /\bbar\b|\bpub\b|arcade|karaoke|entertain|lounge|brewery/i, Barbershop: /barber/i, 'Florist & gifts': /florist|flower|gift/i,
  'Auto repair': /auto|mechanic|car repair|\btires?\b|collision|body shop/i, 'Solar & energy': /solar|energy|generator/i,
  'Pest control & services': /pest|termite|exterminat|mosquito/i, 'Vacation rentals': /vacation|short.term rental|airbnb|villa/i,
  'Moving & hauling': /moving|movers|hauling|junk|storage/i, Construction: /construct|contractor|builder|remodel|roofing|roofer/i,
  'Kids & lessons': /\bkids?\b|child|swim|lessons?|tutor|daycare|\bcamp\b/i, 'Print & promo': /\bprint|screen print|embroider|promo|\bsigns?\b/i,
  'Dental & medical': /dent|orthodont|medical|clinic/i, 'Events & venues': /venue|wedding|\bevents?\b|banquet|ballroom/i,
  'Food truck': /food truck|\btacos?\b|taqueria|street food/i, 'Web & software': /web design|website|software|developer|digital agency/i,
  'Charters & outdoors': /charter|fishing|\bboats?\b|marina|captain/i, 'Law firm': /\blaw\b|attorney|lawyer|legal|injury/i,
  'Med spa & beauty': /med ?spa|aesthetic|botox|skin ?care|facial/i, 'Home care': /home care|caregiver|in-home|companion care|senior care/i,
  'Professional services': /bookkeep|accounting|accountant|\bcpa\b|\btax\b|consult|notary/i, 'Food & café': /cafe|café|bakery|coffee|restaurant|\bdeli\b|pastr/i,
  'IT services': /it services|managed it|network|cyber|it support/i, Fitness: /\bgym\b|fitness|personal train|crossfit|yoga|pilates|boxing|martial/i,
  'Salon & spa': /salon|\bspa\b|\bhair\b|nails?\b|lash|brow|stylist/i, 'Home services': /lawn|landscap|\bpool|cleaning|maid|pressure wash|handyman|home service/i
};
function forBusiness(businessType) {
  const t = String(businessType || '');
  if (!t.trim()) return [];
  return STYLES.filter(st => INDUSTRY_WORDS[st.industry] && INDUSTRY_WORDS[st.industry].test(t)).map(st => PREFIX + st.id);
}

module.exports = { PREFIX, STYLES, BLUEPRINTS, BLUEPRINT_IDS, get, isLib, palette, blueprintOf, tokens, wrapAttrs, fontParams, themeEntry, THEME_ENTRIES, HINTS, forBusiness };
